// Native cuDSS arithmetic on the exact Fortran input bytes. No Fortran compiler claim.
#include "rewrite_runtime.hpp"
#include <cudss.h>
using namespace rewrite;
#include "cuda_uniform_binding.hpp"
int main(){try{identity();const char*in=std::getenv("REWRITE_INPUT");if(!in)throw std::runtime_error("input required");std::ifstream cfg(std::string(in)+"/config.txt");std::string kind;int count;cfg>>kind>>count;if(!cfg||count<1||count>16)throw std::runtime_error("config");
for(int batch=0;batch<count;++batch){int n,nnz,nrhs,ldb,ldx,base,typ,reorder;cfg>>n>>nnz>>nrhs>>ldb>>ldx>>base>>typ>>reorder;if(!cfg||n<1||n>64||nnz<n||nnz>n*n||nrhs<1||nrhs>32||ldb<n||ldx<n)throw std::runtime_error("shape");std::string label="b"+std::to_string(batch);auto r=read<int>(label+"_rows",n+1),c=read<int>(label+"_columns",nnz);auto v=read<double>(label+"_values",nnz),b=read<double>(label+"_B",ldb*nrhs),initial=read<double>(label+"_X",ldx*nrhs);Buffer<int>dr(r),dc(c);Buffer<double>dv(v),db(b),dx(initial);cudssHandle_t h;cudssConfig_t conf;cudssData_t data;cudssMatrix_t a,bm,xm;RW_CHECK(cudssCreate(&h));RW_CHECK(cudssConfigCreate(&conf));RW_CHECK(cudssDataCreate(h,&data));RW_CHECK(cudssMatrixCreateCsr(&a,n,n,nnz,dr.p,nullptr,dc.p,dv.p,CUDA_R_32I,CUDA_R_32I,CUDA_R_64F,typ?CUDSS_MTYPE_SPD:CUDSS_MTYPE_GENERAL,typ?CUDSS_MVIEW_UPPER:CUDSS_MVIEW_FULL,base?CUDSS_BASE_ONE:CUDSS_BASE_ZERO));RW_CHECK(cudssMatrixCreateDn(&bm,n,nrhs,ldb,db.p,CUDA_R_64F,CUDSS_LAYOUT_COL_MAJOR));RW_CHECK(cudssMatrixCreateDn(&xm,n,nrhs,ldx,dx.p,CUDA_R_64F,CUDSS_LAYOUT_COL_MAJOR));std::vector<int>phase={0};RW_CHECK(cudssExecute(h,CUDSS_PHASE_REORDERING,conf,data,a,xm,bm));sync();phase.push_back(1);std::vector<int>rp(n),cp(n);size_t bytes=0;RW_CHECK(cudssDataGet(h,data,CUDSS_DATA_PERM_REORDER_ROW,rp.data(),n*sizeof(int),&bytes));if(bytes!=n*sizeof(int))throw std::runtime_error("row query size");RW_CHECK(cudssDataGet(h,data,CUDSS_DATA_PERM_REORDER_COL,cp.data(),n*sizeof(int),&bytes));if(bytes!=n*sizeof(int))throw std::runtime_error("column query size");for(int&i:rp)i-=base;for(int&i:cp)i-=base;RW_CHECK(cudssExecute(h,CUDSS_PHASE_SYMBOLIC_FACTORIZATION,conf,data,a,xm,bm));auto rc=cudssExecute(h,CUDSS_PHASE_FACTORIZATION,conf,data,a,xm,bm);sync();phase.push_back(2);int info=0;RW_CHECK(cudssDataGet(h,data,CUDSS_DATA_INFO,&info,sizeof(info),&bytes));if(rc&&!info)info=int(rc);if(!info){RW_CHECK(cudssExecute(h,CUDSS_PHASE_SOLVE,conf,data,a,xm,bm));phase.push_back(3);}sync();emit(label+"_dimensions",std::vector<int>{n,nnz,nrhs,ldb,ldx,base,typ});emit(label+"_permutation",rp);emit(label+"_column_permutation",cp);emit(label+"_phase",phase);emit(label+"_info",std::vector<int>{info});emit(label+"_solution",dx.get());emit(label+"_B_after",db.get());RW_CHECK(cudssMatrixDestroy(a));RW_CHECK(cudssMatrixDestroy(bm));RW_CHECK(cudssMatrixDestroy(xm));RW_CHECK(cudssDataDestroy(h,data));RW_CHECK(cudssConfigDestroy(conf));RW_CHECK(cudssDestroy(h));if(info)return 2;}
if(kind=="uniform_batch")native_uniform_selected();return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
